"""Original critical-care organ support: liver failure, ECMO and abdominal emergencies."""
from create_critical_renal_neuro_support import rows,q,AK,ST,CE,SE,ref
LF=ref('AASLD acute liver failure clinical guidance','https://www.aasld.org/liver-fellow-network/core-series/back-basics/defining-and-managing-acute-liver-failure')
VV=ref('ELSO adult VV-ECMO guideline: 2021','https://pmc.ncbi.nlm.nih.gov/articles/PMC8315725/')
VA=ref('ELSO interim adult VA-ECMO guideline','https://doi.org/10.1097/MAT.0000000000001510')

q('A previously healthy adult develops jaundice, INR 2.2 and new hepatic encephalopathy over 2 weeks without established cirrhosis. Which syndrome is most consistent?', 'Acute liver failure',[
 ('Compensated cirrhosis','The presentation lacks a known chronic cirrhotic background and is acutely decompensating.'),('Isolated acute hepatitis without liver failure','Encephalopathy with coagulopathy indicates the failure syndrome.'),('Acute-on-chronic liver failure as established solely by INR','That requires an appropriate underlying chronic disease context.')],
 'Coagulopathy and encephalopathy define more than biochemical hepatitis','**ALF combines acute injury, coagulopathy and encephalopathy in the appropriate noncirrhotic setting.**',['Etiology affects treatment and prognosis.','Aminotransferase magnitude alone does not quantify remaining hepatic function.'], '**Arrange ICU-level assessment and early transplant-center discussion.**',['Investigate drugs, viruses, autoimmune, vascular and metabolic causes as appropriate.','Monitor glucose, lactate, kidney function and neurological status.'],[['Hepatitis','Injury pattern'],['ALF','Coagulopathy plus encephalopathy'],['Priority','Organ support and transplant assessment']],[LF],style='clinical_scenario')

q('An ALF patient progresses to grade III–IV encephalopathy. Which action is particularly important?', 'Protect the airway and coordinate intensive neurocritical and transplant-center care',[
 ('Continue oral intake without airway assessment','Reduced consciousness increases aspiration and airway risk.'),('Wait for a very high MELD score before contacting a transplant center','ALF evaluation should not wait for a chronic-disease scoring threshold.'),('Assume falling ALT proves recovery despite worsening INR and coma','Enzyme reduction can reflect loss of viable hepatocytes rather than recovery.')],
 'Neurological deterioration can be abrupt in ALF','**Severe encephalopathy threatens airway protection and can accompany cerebral edema.**',['Intubation and sedation need an appropriate hemodynamic/neuroprotective plan.','Avoid hypoglycemia, hypoxemia and hypotension.'], '**Refer early enough for definitive options.**',['Use etiology-specific therapy without delaying support.','Track synthetic function and organ trajectory rather than ALT alone.'],[['Coma','Airway risk'],['ALF','Cerebral edema risk'],['Transplant evaluation','Early discussion']],[LF,CE],style='clinical_scenario')

q('Which statement about ammonia in a confused cirrhotic patient is most accurate?', 'It is contextual information; an elevated value alone does not prove hepatic encephalopathy or exclude other causes',[
 ('Any elevation establishes the diagnosis regardless of examination','Ammonia and clinical severity correlate imperfectly.'),('A numeric ammonia value replaces glucose, infection and neurological assessment','Other dangerous causes of confusion still need investigation.'),('Every patient should be intubated solely at one universal ammonia threshold','Airway decisions depend on consciousness, protection and physiology.')],
 'Hepatic encephalopathy is a clinical attribution','**Infection, bleeding, drugs, constipation, electrolyte disturbance and other neurological causes can contribute.**',['Ammonia is influenced by collection and processing.','A normal value in a presumed case should prompt reconsideration, but no single number answers every question.'], '**Find and treat the precipitant.**',['Use appropriate bowel-directed therapy when HE is the diagnosis.','Assess airway and organ support according to clinical severity.'],[['Ammonia','Supporting context'],['Diagnosis','Clinical plus alternative-cause assessment'],['Treatment','Precipitant and syndrome-directed']],[ref('AASLD hepatic encephalopathy guidance','https://www.aasld.org/practice-guidelines/hepatic-encephalopathy')])

q('An ALF patient has INR 3.5 without active bleeding and no imminent invasive procedure. Which coagulation principle is generally appropriate?', 'Do not routinely give plasma solely to normalize INR; assess bleeding risk and procedural needs',[
 ('INR alone mandates repeated plasma in every case','The coagulation balance in liver failure is complex and prophylactic correction adds risks.'),('A prolonged INR proves anticoagulant drug exposure','Synthetic dysfunction can prolong INR without an anticoagulant.'),('No bleeding assessment is needed because ALF can never cause hemorrhage','Clinical bleeding and procedure risks still require careful assessment.')],
 'An abnormal INR is not an automatic transfusion order','**Liver failure alters both procoagulant and anticoagulant pathways.**',['Unnecessary plasma can cause volume complications and obscure INR trends.','Active bleeding or a necessary procedure can justify targeted correction.'], '**Use clinical context and appropriate hemostatic testing.**',['Evaluate platelets and fibrinogen as relevant.','Do not delay a life-saving procedure for an unreasoned attempt at perfect numbers.'],[['INR','Synthetic function/context marker'],['No bleeding/procedure','Avoid routine number correction'],['Bleeding/procedure','Targeted individualized management']],[LF],style='clinical_scenario')

q('Which distinction between VV-ECMO and VA-ECMO is correct?', 'VV primarily provides gas exchange and depends on native cardiac function; VA also provides direct circulatory support',[
 ('VV and VA provide identical direct arterial pump support','VV returns blood to the venous circulation rather than directly replacing systemic arterial output.'),('VA cannot oxygenate blood','VA includes an oxygenator and can provide gas exchange.'),('VV always bypasses the right and left heart completely','Blood returned venously still traverses the native circulation.')],
 'Select configuration according to the failing organ system','**VV supports respiratory failure when native circulation can deliver oxygenated blood.**',['VA supports selected combined or circulatory failure phenotypes.','Configuration can be more complex in mixed disease.'], '**Define a bridge goal and assess reversibility.**',['Device selection depends on the physiology and specialist resources.','Neither configuration removes the need to treat the cause.'],[['VV','Respiratory support'],['VA','Circulatory plus gas-exchange support'],['Selection','Organ failure and treatment goal']],[VV,VA])

q('A patient has potentially reversible severe ARDS with refractory gas-exchange failure despite optimized lung-protective ventilation and proning. What is appropriate?', 'Early discussion with an experienced ECMO center for selection assessment',[
 ('Wait until prolonged irreversible multiorgan injury develops before referral','Late deterioration can reduce candidacy and safe transport options.'),('Use VV-ECMO routinely for every mild ARDS patient','The risk-benefit profile requires severe disease and selection.'),('Assume ECMO is impossible solely because the patient is proned','Proning is part of optimized care and does not itself preclude ECMO assessment.')],
 'Referral timing is different from automatic cannulation','**Selected severe ARDS patients can be considered for VV-ECMO.**',['Reversibility, ventilation duration, comorbidities and organ injury affect candidacy.','Center expertise and transport safety matter.'], '**Continue protective care while obtaining expert advice.**',['A referral does not guarantee benefit or eligibility.','Discuss goals, complications and alternatives.'],[['Selection','Severe refractory but potentially reversible disease'],['Timing','Before avoidable irreversible decline'],['Center','Experienced multidisciplinary care']],[VV,ref('ATS ARDS management update: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC10870893/')],style='clinical_scenario')

q('During VV-ECMO, oxygenated return blood is being immediately drawn back into the drainage cannula. What is this called?', 'Recirculation',[
 ('Differential aortic hypoxemia','That describes a different problem, classically during peripheral VA support.'),('Oxygenator sweep-gas failure','This is a separate circuit problem.'),('Isolated pulmonary shunt without a circuit contribution','The described immediate return-to-drainage pathway is recirculation.')],
 'Effective patient flow can be lower than displayed pump flow','**Recirculation wastes some oxygenated circuit blood by draining it again.**',['Cannula position, separation and flow relationships influence it.','Systemic hypoxemia on VV-ECMO has several other causes as well.'], '**Assess cannula position, circuit and patient physiology.**',['Do not increase pump speed blindly if it worsens recirculation or drainage.','Review hemoglobin, cardiac output, oxygenator performance and native lung function.'],[['Pump flow','Not always effective systemic support'],['Recirculation','Return blood re-enters drainage'],['Correction','Configuration/position and flow review']],[VV])

q('During femoral VA-ECMO, native cardiac ejection recovers while severe lung failure persists. Right-arm oxygenation worsens despite well-oxygenated femoral blood. Which mechanism is most likely?', 'Differential upper-body hypoxemia',[
 ('VV recirculation as the only possible explanation','This is a different configuration and mechanism.'),('A universal sign of complete cardiac standstill','The problem arises partly because native ejection has recovered.'),('A benign pulse-oximeter artifact that needs no arterial confirmation','The pattern can threaten coronary and cerebral oxygen delivery.')],
 'Two circulatory streams can deliver different oxygen content','**Poorly oxygenated native output can perfuse the upper body while retrograde ECMO flow supplies the lower body.**',['Right-radial arterial monitoring helps assess upper-body oxygenation.','Configuration and lung/cardiac support may need adjustment.'], '**Treat the patient and circuit as one integrated system.**',['Confirm the distribution and assess native lung function.','Use expert-guided support changes rather than assume a normal femoral gas protects the brain.'],[['Native output','May be poorly oxygenated'],['Femoral ECMO return','Can oxygenate lower body'],['Right radial','Useful upper-body monitoring site']],[VA],style='clinical_scenario')

q('A critically ill patient has a tense abdomen, sustained bladder-measured intra-abdominal pressure 24 mmHg, oliguria and worsening ventilation. Which diagnosis is most consistent?', 'Abdominal compartment syndrome',[
 ('Intra-abdominal hypertension without organ dysfunction','New organ dysfunction with pressure above twenty supports compartment syndrome.'),('Simple constipation as established without further assessment','The pressure and organ failure require urgent evaluation.'),('Isolated intrinsic AKI unrelated to abdominal pressure','The overall pattern suggests a mechanical contribution.')],
 'Pressure plus organ dysfunction defines the dangerous syndrome','**ACS is sustained intra-abdominal pressure above 20 mmHg with new organ dysfunction.**',['Bladder pressure measurement must use a standardized technique.','Fluid accumulation, edema, bleeding and other abdominal processes can contribute.'], '**Relieve reversible causes and obtain urgent surgical/critical-care assessment.**',['Decompression may be required when medical measures fail or organ threat is severe.','Avoid adding fluid blindly to pressure-related oliguria.'],[['IAP >20','Pressure criterion'],['New organ dysfunction','Defines compartment syndrome'],['Management','Cause correction and selected decompression']],[ref('WSACS consensus definitions and management guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC3680657/')],style='clinical_scenario')

q('A patient with atrial fibrillation has sudden severe abdominal pain out of proportion to examination. Initial lactate is normal. What is the best diagnostic principle?', 'Obtain urgent CT angiography when acute mesenteric ischemia is suspected; normal early lactate does not exclude it',[
 ('Exclude ischemia because lactate is normal','Early ischemia may not raise systemic lactate.'),('Wait for peritonitis before imaging','That can indicate advanced infarction and harmful delay.'),('Use a plain film as a definitive early exclusion test','Its early sensitivity is inadequate.')],
 'A normal marker cannot exclude a time-critical vascular diagnosis','**CTA is the principal diagnostic imaging pathway in suspected acute mesenteric ischemia.**',['Embolic, thrombotic and nonocclusive mechanisms require different definitive approaches.','Peritonitis or instability can require immediate operative involvement.'], '**Consult the relevant surgical/vascular team early.**',['Support perfusion and treat precipitating factors.','Do not let renal-risk concerns automatically delay necessary life-saving imaging.'],[['Early lactate','Can be normal'],['CTA','Defines vascular and bowel findings'],['Delay','Raises infarction risk']],[ref('WSES acute mesenteric ischemia guideline: 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC9580452/')],style='clinical_scenario')

q('A patient with necrotizing pancreatitis has no evidence of infected necrosis or another bacterial infection. Which antibiotic principle is appropriate?', 'Do not give routine prophylactic antibiotics solely for sterile necrosis',[
 ('Give carbapenem prophylaxis in every necrotizing case','Routine prophylaxis has not shown the required benefit.'),('Use persistent fever alone as definitive proof of infected necrosis','Sterile inflammation can cause fever.'),('Never treat any infection during pancreatitis','Confirmed or strongly suspected infection requires appropriate treatment.')],
 'Distinguish sterile inflammation from infection','**Necrosis alone does not establish bacterial infection.**',['Gas in a collection, cultures and the clinical trajectory can support an infected diagnosis.','Cholangitis, pneumonia and line infection are other possible infectious sources.'], '**Provide organ support and appropriate enteral nutrition.**',['Use a step-up source-control strategy when infected necrosis requires intervention.','Do not equate antibiotics with definitive drainage when source control is needed.'],[['Sterile necrosis','No routine prophylaxis'],['Infection','Treat appropriately'],['Source control','Selected staged approach']],[ref('ACG acute pancreatitis guideline: 2024','https://doi.org/10.14309/ajg.0000000000002645')],style='clinical_scenario')

q('A ventilated patient receiving escalating vasopressors develops abdominal distension, feeding intolerance and worsening organ function. Which principle is most appropriate?', 'Reassess perfusion and possible bowel ischemia rather than automatically advance enteral feeding',[
 ('Increase feeding rapidly because all shock patients need full calories immediately','Uncontrolled shock and possible gut ischemia require caution.'),('Assume distension proves simple constipation in every case','The severe clinical setting requires a broader differential.'),('Use normal earlier imaging to exclude a new abdominal emergency','The physiology and pathology may have changed.')],
 'Feeding tolerance is a clinical signal, not merely a residual-volume number','**Gut hypoperfusion and nonocclusive ischemia are concerns in severe unstable illness.**',['Distension has other causes, including ileus, obstruction and abdominal hypertension.','Nutrition should follow resuscitation and a safe perfusion context.'], '**Investigate a deteriorating abdomen promptly.**',['Review vasopressor trajectory, examination and imaging needs.','Do not delay surgical evaluation when ischemia or peritonitis is suspected.'],[['Uncontrolled shock','Feeding caution'],['New abdominal signs','Investigate'],['Nutrition','Advance when clinically safe']],[ref('ESPEN ICU nutrition guideline: 2023 practical revision','https://doi.org/10.1016/j.clnu.2023.07.011'),ref('WSES mesenteric ischemia guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC9580452/')],style='clinical_scenario')

if __name__=='__main__':print(f'Critical organ support cumulative draft: {len(rows)} questions')
